package glitch

import data.glitch_lib

insecure_protocols = {"http", "ftp", "udp"}
disabled_integrity_flags = {"disable_checksum", "integrity_check", "enable_tls", "validate_certs", "gpgcheck", "ssl_verify", "tls_verify"}
weak_algorithms = {"md5", "sha1"}
storage_attributes = {"bucket", "container", "database", "table", "queue"}
integrity_attributes = {"versioning", "checksum", "validation", "integrity", "checksum_algorithm", "gpgcheck"}

has_insecure_protocol_string(str_val) {
    regex.match(".*(http://|ftp://|udp://).*", str_val)
}

has_insecure_protocol_string(str_val) {
    insecure_protocols[_] == str_val
}

has_insecure_protocol(expr) {
    expr.ir_type == "String"
    has_insecure_protocol_string(expr.value)
}

has_insecure_protocol(expr) {
    expr.ir_type == "VariableReference"
    has_insecure_protocol_string(expr.value)
}

is_disabled_integrity_flag(attr) {
    disabled_integrity_flags[_] == attr.name
    attr.value.ir_type == "Boolean"
    attr.value.value == false
}

is_disabled_integrity_flag(attr) {
    disabled_integrity_flags[_] == attr.name
    attr.value.ir_type == "Integer"
    attr.value.value == 0
}

is_disabled_integrity_flag(attr) {
    attr.name == "integrity_check"
    attr.value.ir_type == "String"
    attr.value.value == "disabled"
}

is_disabled_integrity_flag(attr) {
    attr.name == "validate_certs"
    attr.value.ir_type == "String"
    attr.value.value == "no"
}

is_disabled_integrity_flag(attr) {
    attr.name == "gpgcheck"
    attr.value.ir_type == "Integer"
    attr.value.value == 0
}

is_weak_algorithm(attr) {
    attr.name == "algorithm"
    attr.value.ir_type == "String"
    weak_algorithms[_] == attr.value.value
}

is_weak_algorithm(attr) {
    attr.name == "hash"
    attr.value.ir_type == "String"
    weak_algorithms[_] == attr.value.value
}

is_weak_algorithm(attr) {
    attr.name == "checksum_algorithm"
    attr.value.ir_type == "String"
    weak_algorithms[_] == attr.value.value
}

is_storage_resource(node) {
    node.ir_type == "AtomicUnit"
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    storage_attributes[_] == attr.name
}

has_integrity_attribute(node) {
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    integrity_attributes[_] == attr.name
}

find_disabled_integrity_in_hash(hash_node) {
    walk(hash_node, [path, n])
    n.ir_type == "KeyValue"
    disabled_integrity_flags[_] == n.name
    n.value.ir_type == "Integer"
    n.value.value == 0
}

find_disabled_integrity_in_hash(hash_node) {
    walk(hash_node, [path, n])
    n.ir_type == "KeyValue"
    n.name == "gpgcheck"
    n.value.ir_type == "Integer"
    n.value.value == 0
}

check_variable_for_disabled_integrity(variable) {
    variable.ir_type == "Variable"
    walk(variable.value, [path, n])
    n.ir_type == "KeyValue"
    is_disabled_integrity_flag(n)
}

check_variable_for_disabled_integrity(variable) {
    variable.ir_type == "Variable"
    walk(variable.value, [path, n])
    n.ir_type == "Hash"
    find_disabled_integrity_in_hash(n)
}

has_insecure_protocol_in_element(element) {
    attrs := glitch_lib.all_attributes(element)
    attr := attrs[_]
    has_insecure_protocol(attr.value)
}

has_insecure_protocol_in_element(element) {
    element.ir_type == "AtomicUnit"
    has_insecure_protocol_string(element.code)
}

has_insecure_protocol_in_element(element) {
    element.ir_type == "Variable"
    has_insecure_protocol_string(element.code)
}

has_disabled_integrity_in_element(element) {
    attrs := glitch_lib.all_attributes(element)
    attr := attrs[_]
    is_disabled_integrity_flag(attr)
}

has_disabled_integrity_in_element(element) {
    check_variable_for_disabled_integrity(element)
}

has_weak_algorithm_in_element(element) {
    attrs := glitch_lib.all_attributes(element)
    attr := attrs[_]
    is_weak_algorithm(attr)
}

collect_elements(parent) = elements {
    atomic_units := glitch_lib.all_atomic_units(parent)
    variables := glitch_lib.all_variables(parent)
    elements := {e | e := atomic_units[_]} | {e | e := variables[_]}
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    elements := collect_elements(parent)
    element := elements[_]
    has_insecure_protocol_in_element(element)
    result := {
        "type": "sec_no_int_check",
        "element": element,
        "path": parent.path,
        "description": "Unprotected data transmission - Protocol lacks integrity checks (e.g., HTTP, FTP, UDP without TLS). (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    elements := collect_elements(parent)
    element := elements[_]
    has_disabled_integrity_in_element(element)
    result := {
        "type": "sec_no_int_check",
        "element": element,
        "path": parent.path,
        "description": "Explicitly disabled integrity features - Checksum or integrity check is turned off. (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    elements := collect_elements(parent)
    element := elements[_]
    has_weak_algorithm_in_element(element)
    result := {
        "type": "sec_no_int_check",
        "element": element,
        "path": parent.path,
        "description": "Weak integrity algorithm - Using outdated/broken algorithms (e.g., MD5, SHA1) for integrity checks. (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    is_storage_resource(node)
    not has_integrity_attribute(node)
    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Storage integrity omission - Cloud storage or database lacks versioning/checksum/validation settings. (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    protocol_attr := attrs[_]
    protocol_attr.name == "protocol"
    has_insecure_protocol(protocol_attr.value)
    encryption_attrs = {"tls", "encryption", "ssl"}
    has_encryption := count({enc_attr |
        enc_attr := attrs[_]
        encryption_attrs[_] == enc_attr.name
        enc_attr.value.ir_type == "Boolean"
        enc_attr.value.value == true
    }) > 0
    not has_encryption
    result := {
        "type": "sec_no_int_check",
        "element": protocol_attr,
        "path": parent.path,
        "description": "Protocol mismatch for security - Service uses insecure protocol without TLS/encryption for sensitive data. (CWE-353)"
    }
}

